async (page) => {
  const f = page.frameLocator('iframe');
  await f.getByLabel('Enterprise').check();
  const seats = f.getByLabel('Seats');
  await seats.fill('14');
  const before = await seats.inputValue();
  await f.getByRole('button', { name: 'Confirm plan' }).click();
  await page.waitForTimeout(1000);
  const enterprise = await f.getByLabel('Enterprise').isChecked();
  const after = await seats.inputValue();
  return { before, after, enterprise };
}

